#!/usr/local/bin/prhm-node
'use strict';
const fs=require('node:fs');
const path=require('node:path');
const crypto=require('node:crypto');
const cp=require('node:child_process');
const ACTION='company_os_dashboard_v1';
const NODE='/usr/local/bin/prhm-node';
const HTTPD='/usr/sbin/httpd';
const SYSTEMCTL='/usr/bin/systemctl';
const PSQL='/usr/bin/psql';
const PASS_FILE='/etc/prhm-p0-db-helper/postgres_superuser_password';
const APP_DIR='/opt/prhm-company-os-dashboard';
const AUTH_DIR='/etc/prhm-company-os-dashboard';
const AUTH_FILE=AUTH_DIR+'/auth.json';
const STATE_DIR='/var/lib/prhm-company-os-dashboard';
const SNAPSHOT=STATE_DIR+'/snapshot.json';
const RESULT_DIR='/var/lib/prhm-agent-selfmaint-exec/company-os-dashboard-v1';
const RESULT_FILE=RESULT_DIR+'/latest.json';
const CREDENTIALS='/root/company-os-dashboard-credentials.txt';
const HTTP_VHOST='/etc/httpd/conf.d/prhm-vhosts.conf';
const HTTPS_VHOST='/etc/httpd/conf.d/prhm-vhosts-ssl.conf';
const EXPECTED_HTTP_SHA='3df02ee3a386c2ef144131225c037d20d5348bdc969adcf14bd556acd864fe40';
const EXPECTED_HTTPS_SHA='39e146f24e277c8e90f72247828358da14caf4a8f3d0bcb49803d9318db3304c';
const PORT=18135;
const ARTIFACTS=Object.freeze({"server.js":{"b64":"","sha256":"de2964c4cb14c135c0bb1b5573b39230ff92de15901c30ab1e48ebaf4c13dd3a"},"collector.js":{"b64":"","sha256":"01b684c5d305ca00fde5fa223f0545d34ee109bd1ac49ad20b6ab812c78fc72b"},"public/index.html":{"b64":"","sha256":"0a386ae24fbc0a513ab7eb48e000297aaa1b470e7557058dea840d31303fc1f7"},"public/styles.css":{"b64":"","sha256":"661dcfa380471af64bb50334a3ea92cc9e8421ddf3d494a99448477fc4ddba0f"},"public/app.js":{"b64":"","sha256":"b2d0fe6ded54f57b7e1b51de42b88d6ff18c2a79eccc9c5b8d40d255e0a585e1"}});
const WEB_UNIT='/etc/systemd/system/prhm-company-os-dashboard.service';
const COLLECTOR_UNIT='/etc/systemd/system/prhm-company-os-dashboard-collector.service';
const COLLECTOR_TIMER='/etc/systemd/system/prhm-company-os-dashboard-collector.timer';
const PROXY_BLOCK='    ProxyPass /company-os http://127.0.0.1:18135/company-os retry=0 connectiontimeout=3 timeout=15\n    ProxyPassReverse /company-os http://127.0.0.1:18135/company-os\n';
const PROXY_ANCHOR='    ProxyPassReverse /health http://127.0.0.1:8123/health\n';
const WEB_SERVICE=`[Unit]
Description=PRHM Company OS read-only dashboard
After=network.target prhm-company-os-dashboard-collector.service

[Service]
Type=simple
User=apache
Group=apache
ExecStart=/usr/local/bin/prhm-node /opt/prhm-company-os-dashboard/server.js
Restart=on-failure
RestartSec=3s
UMask=0027
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
LockPersonality=true
RestrictSUIDSGID=true
RestrictNamespaces=true
RestrictRealtime=true
CapabilityBoundingSet=
AmbientCapabilities=
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
ReadOnlyPaths=/opt/prhm-company-os-dashboard /etc/prhm-company-os-dashboard /var/lib/prhm-company-os-dashboard
InaccessiblePaths=/root /etc/prhm-p0-db-helper /var/lib/prhm-agent-selfmaint-exec

[Install]
WantedBy=multi-user.target
`;
const COLLECTOR_SERVICE=`[Unit]
Description=PRHM Company OS read-only snapshot collector
After=network.target

[Service]
Type=oneshot
User=root
Group=root
ExecStart=/usr/local/bin/prhm-node /opt/prhm-company-os-dashboard/collector.js
UMask=0027
NoNewPrivileges=true
PrivateTmp=true
PrivateDevices=true
ProtectSystem=strict
ProtectHome=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
LockPersonality=true
RestrictSUIDSGID=true
RestrictRealtime=true
CapabilityBoundingSet=CAP_CHOWN CAP_DAC_READ_SEARCH
AmbientCapabilities=
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6
ReadOnlyPaths=/opt/prhm-company-os-dashboard /etc/prhm-p0-db-helper /var/lib/prhm-agent-selfmaint-exec
ReadWritePaths=/var/lib/prhm-company-os-dashboard
`;
const COLLECTOR_TIMER_TEXT=`[Unit]
Description=Refresh PRHM Company OS dashboard snapshot

[Timer]
OnBootSec=1min
OnUnitActiveSec=5min
Persistent=true
Unit=prhm-company-os-dashboard-collector.service

[Install]
WantedBy=timers.target
`;
function fail(m){throw new Error(m)}
function shaBuf(b){return crypto.createHash('sha256').update(b).digest('hex')}
function shaFile(f){return shaBuf(fs.readFileSync(f))}
function exec(file,args,opt={}){const r=cp.spawnSync(file,args,{encoding:'utf8',maxBuffer:4*1024*1024,...opt});if(r.error)fail('exec_error:'+file+':'+r.error.message);if(r.status!==0)fail('exec_failed:'+file+':'+r.status+':'+String(r.stderr||'').slice(-1500));return r}
function replaceOnce(s,a,b,label){const i=s.indexOf(a);if(i<0)fail('anchor_missing:'+label);if(s.indexOf(a,i+1)>=0)fail('anchor_not_unique:'+label);return s.slice(0,i)+a+b+s.slice(i+a.length)}
function atomic(file,data,mode){const tmp=file+'.tmp-'+process.pid+'-'+Date.now();fs.writeFileSync(tmp,data,{mode});fs.chmodSync(tmp,mode);fs.renameSync(tmp,file)}
function rm(p){try{fs.rmSync(p,{recursive:true,force:true})}catch{}}
function readFlags(){const pw=fs.readFileSync(PASS_FILE,'utf8').trim();if(!pw)fail('db_password_empty');const env={...process.env,PGPASSWORD:pw,PGOPTIONS:'-c default_transaction_read_only=on -c statement_timeout=12000 -c lock_timeout=1500'};try{const sql="SELECT json_object_agg(flag,enabled) FROM automation.p0_feature_flags";const r=exec(PSQL,['-X','-At','-v','ON_ERROR_STOP=1','-h','127.0.0.1','-p','55434','-U','leadops_admin','-d','leadops'],{input:sql,env,timeout:30000});return JSON.parse(String(r.stdout||'').trim())}finally{delete env.PGPASSWORD}}
function verifyFlags(){const f=readFlags();const dangerous=['P0_DECISION_ENABLED','AUTO_PROPOSAL_ENABLED','PROPOSAL_AUTO_SEND_ENABLED','FOLLOWUP_ENABLED','AUTO_NEGOTIATION_ENABLED','AUTO_ASSIGNMENT_ENABLED','AUTO_QA_ENABLED','AUTO_DELIVERY_ENABLED','AUTO_BILLING_ENABLED','AUTO_PAYMENT_MATCH_ENABLED','UPSELL_ENABLED','REACTIVATION_ENABLED'];if(f.P0_SHADOW_MODE!==true)fail('shadow_mode_not_true');for(const k of dangerous)if(f[k]!==false)fail('unsafe_flag:'+k+':'+f[k]);return f}
function portFree(){const r=cp.spawnSync('/usr/sbin/ss',['-ltn'],{encoding:'utf8'});if(r.status!==0)fail('ss_failed');return !String(r.stdout||'').split(/\r?\n/).some(x=>x.includes(':'+PORT+' '))}
function httpdSyntax(){exec(HTTPD,['-t'],{timeout:30000})}
function baseline(){if(shaFile(HTTP_VHOST)!==EXPECTED_HTTP_SHA)fail('http_vhost_sha_mismatch');if(shaFile(HTTPS_VHOST)!==EXPECTED_HTTPS_SHA)fail('https_vhost_sha_mismatch');for(const p of [APP_DIR,AUTH_DIR,STATE_DIR,WEB_UNIT,COLLECTOR_UNIT,COLLECTOR_TIMER,CREDENTIALS])if(fs.existsSync(p))fail('dashboard_path_already_exists:'+p);if(!portFree())fail('dashboard_port_in_use');for(const [rel,a] of Object.entries(ARTIFACTS)){const b=Buffer.from(a.b64,'base64');if(shaBuf(b)!==a.sha256)fail('embedded_artifact_sha_invalid:'+rel);if(rel.endsWith('.js')){const tmp='/tmp/prhm-dashboard-check-'+process.pid+'-'+path.basename(rel);try{fs.writeFileSync(tmp,b,{mode:0o600});exec(NODE,['--check',tmp])}finally{rm(tmp)}}}httpdSyntax();const flags=verifyFlags();return flags}
function preflight(){const flags=baseline();return {ok:true,schema_version:'prhm.host-action-bootstrap-preflight.v1',preflight_only:true,action:ACTION,url:'https://agent.prhm.ir/company-os/',port:PORT,artifact_shas:Object.fromEntries(Object.entries(ARTIFACTS).map(([k,v])=>[k,v.sha256])),vhost_shas:{http:EXPECTED_HTTP_SHA,https:EXPECTED_HTTPS_SHA},safety:{P0_SHADOW_MODE:flags.P0_SHADOW_MODE,P0_DECISION_ENABLED:flags.P0_DECISION_ENABLED,PROPOSAL_AUTO_SEND_ENABLED:flags.PROPOSAL_AUTO_SEND_ENABLED},database_mutation:false,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false,production_mutation:false}}
function persist(x){fs.mkdirSync(RESULT_DIR,{recursive:true,mode:0o700});atomic(RESULT_FILE,JSON.stringify(x,null,2)+'\n',0o600)}
function installArtifacts(){fs.mkdirSync(APP_DIR+'/public',{recursive:true,mode:0o755});for(const [rel,a] of Object.entries(ARTIFACTS)){const dst=path.join(APP_DIR,rel);fs.mkdirSync(path.dirname(dst),{recursive:true,mode:0o755});atomic(dst,Buffer.from(a.b64,'base64'),rel.endsWith('.js')?0o755:0o644);if(shaFile(dst)!==a.sha256)fail('artifact_post_sha_mismatch:'+rel)}}
function makeAuth(){const password=crypto.randomBytes(24).toString('base64url');const digest=crypto.createHash('sha256').update(password).digest('hex');fs.mkdirSync(AUTH_DIR,{recursive:true,mode:0o750});atomic(AUTH_FILE,JSON.stringify({username:'mohammad',password_sha256:digest},null,2)+'\n',0o640);fs.chownSync(AUTH_FILE,0,48);fs.chmodSync(AUTH_FILE,0o640);atomic(CREDENTIALS,'URL=https://agent.prhm.ir/company-os/\nUSERNAME=mohammad\nPASSWORD='+password+'\n',0o600);return {username:'mohammad',password}}
function writeUnits(){atomic(WEB_UNIT,WEB_SERVICE,0o644);atomic(COLLECTOR_UNIT,COLLECTOR_SERVICE,0o644);atomic(COLLECTOR_TIMER,COLLECTOR_TIMER_TEXT,0o644)}
function patchVhosts(){const h=fs.readFileSync(HTTP_VHOST,'utf8'),s=fs.readFileSync(HTTPS_VHOST,'utf8');if(h.includes('ProxyPass /company-os')||s.includes('ProxyPass /company-os'))fail('company_os_proxy_already_present');atomic(HTTP_VHOST,replaceOnce(h,PROXY_ANCHOR,PROXY_BLOCK,'http_proxy_anchor'),0o644);atomic(HTTPS_VHOST,replaceOnce(s,PROXY_ANCHOR,PROXY_BLOCK,'https_proxy_anchor'),0o644)}
function curl(args){return exec('/usr/bin/curl',['-fsS','--max-time','8',...args],{timeout:15000}).stdout}
function verifyInstall(cred){for(let i=0;i<40;i++){const r=cp.spawnSync('/usr/bin/curl',['-fsS','--max-time','2','http://127.0.0.1:18135/health'],{encoding:'utf8'});if(r.status===0){try{const x=JSON.parse(r.stdout);if(x.ok===true&&x.version==='1.0.0-read-only')break}catch{}}if(i===39)fail('dashboard_health_not_ready');Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,200)}const auth=cred.username+':'+cred.password;const html=String(curl(['-H','X-Forwarded-Proto: https','-u',auth,'http://127.0.0.1:18135/company-os/']));if(!html.includes('Company OS'))fail('dashboard_html_invalid');const snap=JSON.parse(String(curl(['-H','X-Forwarded-Proto: https','-u',auth,'http://127.0.0.1:18135/company-os/api/snapshot'])));if(snap.schema_version!=='prhm.company-os-dashboard.snapshot.v1'||snap.read_only!==true)fail('snapshot_invalid');const unauth=cp.spawnSync('/usr/bin/curl',['-sS','-o','/dev/null','-w','%{http_code}','-H','Host: agent.prhm.ir','-H','X-Forwarded-Proto: https','http://127.0.0.1/company-os/'],{encoding:'utf8'});if(String(unauth.stdout).trim()!=='401')fail('apache_unauthorized_status:'+unauth.stdout);const authorized=String(curl(['-H','Host: agent.prhm.ir','-H','X-Forwarded-Proto: https','-u',auth,'http://127.0.0.1/company-os/']));if(!authorized.includes('Company OS'))fail('apache_authorized_proxy_invalid');const redirect=cp.spawnSync('/usr/bin/curl',['-sS','-o','/dev/null','-w','%{http_code}','-H','Host: agent.prhm.ir','http://127.0.0.1/company-os/'],{encoding:'utf8'});if(String(redirect.stdout).trim()!=='301')fail('apache_http_redirect_invalid:'+redirect.stdout);const flags=verifyFlags();return {snapshot_generated_at:snap.generated_at,opportunities:Array.isArray(snap.opportunities)?snap.opportunities.length:0,decisions:Array.isArray(snap.decisions)?snap.decisions.length:0,services:Array.isArray(snap.services)?snap.services.length:0,safety:{P0_SHADOW_MODE:flags.P0_SHADOW_MODE,P0_DECISION_ENABLED:flags.P0_DECISION_ENABLED,PROPOSAL_AUTO_SEND_ENABLED:flags.PROPOSAL_AUTO_SEND_ENABLED}}}
function cleanupInstall(backupDir){try{exec(SYSTEMCTL,['disable','--now','prhm-company-os-dashboard-collector.timer'],{timeout:30000})}catch{}try{exec(SYSTEMCTL,['disable','--now','prhm-company-os-dashboard.service'],{timeout:30000})}catch{}for(const p of [WEB_UNIT,COLLECTOR_UNIT,COLLECTOR_TIMER])rm(p);if(backupDir){const bh=backupDir+'/prhm-vhosts.conf',bs=backupDir+'/prhm-vhosts-ssl.conf';if(fs.existsSync(bh))atomic(HTTP_VHOST,fs.readFileSync(bh),0o644);if(fs.existsSync(bs))atomic(HTTPS_VHOST,fs.readFileSync(bs),0o644)}try{httpdSyntax();exec(SYSTEMCTL,['reload','httpd.service'],{timeout:30000})}catch{}rm(APP_DIR);rm(AUTH_DIR);rm(STATE_DIR);rm(CREDENTIALS);try{exec(SYSTEMCTL,['daemon-reload'],{timeout:30000})}catch{}}
function main(){const args=process.argv.slice(2);if(args.length>1||(args.length===1&&args[0]!=='--preflight-only'))fail('unexpected_arguments');if(process.getuid&&process.getuid()!==0)fail('must_run_as_root');if(args[0]==='--preflight-only'){process.stdout.write(JSON.stringify(preflight())+'\n');return}baseline();const stamp=new Date().toISOString().replace(/[-:.TZ]/g,'').slice(0,14),backupDir='/var/backups/prhm-company-os-dashboard-'+stamp;fs.mkdirSync(backupDir,{recursive:true,mode:0o700});fs.copyFileSync(HTTP_VHOST,backupDir+'/prhm-vhosts.conf',fs.constants.COPYFILE_EXCL);fs.copyFileSync(HTTPS_VHOST,backupDir+'/prhm-vhosts-ssl.conf',fs.constants.COPYFILE_EXCL);fs.chmodSync(backupDir+'/prhm-vhosts.conf',0o600);fs.chmodSync(backupDir+'/prhm-vhosts-ssl.conf',0o600);let ok=false;try{installArtifacts();const cred=makeAuth();fs.mkdirSync(STATE_DIR,{recursive:true,mode:0o750});fs.chownSync(STATE_DIR,0,48);fs.chmodSync(STATE_DIR,0o750);writeUnits();exec(SYSTEMCTL,['daemon-reload']);exec(SYSTEMCTL,['start','prhm-company-os-dashboard-collector.service'],{timeout:60000});if(!fs.existsSync(SNAPSHOT))fail('snapshot_missing_after_collection');patchVhosts();httpdSyntax();exec(SYSTEMCTL,['reload','httpd.service'],{timeout:30000});exec(SYSTEMCTL,['enable','--now','prhm-company-os-dashboard.service'],{timeout:30000});exec(SYSTEMCTL,['enable','--now','prhm-company-os-dashboard-collector.timer'],{timeout:30000});const verify=verifyInstall(cred);ok=true;const result={schema_version:'prhm.host-action-result.v1',ok:true,action:ACTION,installed:true,url:'https://agent.prhm.ir/company-os/',credentials_path:CREDENTIALS,dashboard_health:true,snapshot_schema:'prhm.company-os-dashboard.snapshot.v1',proxy_http_verified:true,proxy_https_header_verified:true,auth_required:true,read_only:true,collector_interval:'5min',backup_dir:backupDir,verify,database_mutation:false,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false};persist(result);process.stdout.write(JSON.stringify(result)+'\n')}catch(e){cleanupInstall(backupDir);const result={schema_version:'prhm.host-action-result.v1',ok:false,action:ACTION,error:String(e&&e.message||e),rollback_verified:shaFile(HTTP_VHOST)===EXPECTED_HTTP_SHA&&shaFile(HTTPS_VHOST)===EXPECTED_HTTPS_SHA,business_mutation:false,p0_live:false,proposal_send:false,bid_send:false};persist(result);throw e}}
try{main()}catch(e){process.stderr.write(String(e&&e.stack||e)+'\n');process.exit(1)}
